def rotate(nums, k):
    n = len(nums)
    for _ in range(k % n):
        last = nums[-1]
        for i in range(n - 1, 0, -1):
            nums[i] = nums[i - 1]
        nums[0] = last

def rotate(nums, k):
    n = len(nums)
    out = [0] * n
    for i, x in enumerate(nums):
        out[(i + k) % n] = x
    nums[:] = out

def rotate(nums, k):
    n = len(nums)
    k %= n

    def rev(lo, hi):
        while lo < hi:
            nums[lo], nums[hi] = nums[hi], nums[lo]
            lo, hi = lo + 1, hi - 1

    rev(0, n - 1)
    rev(0, k - 1)
    rev(k, n - 1)
